import 'server-only';

import type { NextRequest } from 'next/server';

import { getServerEnv } from '@/server/env';

import { ApiError } from './api-error';
import { getRequestMetadata } from './request-metadata';

const captchaHeaderName = 'x-captcha-token';
const googleVerifyUrl = 'https://www.google.com/recaptcha/api/siteverify';

interface GoogleCaptchaResponse {
  success: boolean;
  score?: number;
  action?: string;
  challenge_ts?: string;
  hostname?: string;
  'error-codes'?: string[];
}

export interface CaptchaVerificationResult {
  success: boolean;
  skipped: boolean;
  score?: number;
  action?: string;
}

export function readCaptchaToken(request: NextRequest) {
  return request.headers.get(captchaHeaderName)?.trim() || undefined;
}

export async function verifyCaptchaToken(
  token: string | undefined,
  remoteIp?: string
): Promise<CaptchaVerificationResult> {
  const secret = getServerEnv().captcha.googleSecret;

  if (!secret) {
    return { success: true, skipped: true };
  }

  if (!token) {
    throw new ApiError('BAD_REQUEST', 'Missing captcha challenge token');
  }

  const body = new URLSearchParams({
    secret,
    response: token,
  });

  if (remoteIp) {
    body.set('remote' + 'ip', remoteIp);
  }

  const response = await fetch(googleVerifyUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body,
  });

  if (!response.ok) {
    throw new ApiError('SERVICE_UNAVAILABLE', 'Failed to verify captcha');
  }

  const data = (await response.json()) as GoogleCaptchaResponse;

  if (!data.success) {
    throw new ApiError('UNAUTHORIZED', 'Captcha verification failed');
  }

  return {
    success: true,
    skipped: false,
    score: data.score,
    action: data.action,
  };
}

export async function verifyRequestCaptcha(request: NextRequest) {
  const metadata = getRequestMetadata(request);
  return verifyCaptchaToken(readCaptchaToken(request), metadata.ipAddress);
}

import 'server-only';

import { NextResponse } from 'next/server';

import {
  ApiError,
  internalServerError,
  isApiError,
  jsonError,
} from './api-error';

export interface ApiSuccessBody<T> {
  code: 'OK';
  data: T;
}

export function jsonOk<T>(data: T, init?: ResponseInit) {
  return NextResponse.json<ApiSuccessBody<T>>(
    { code: 'OK', data },
    { status: init?.status ?? 200, headers: init?.headers }
  );
}

export function jsonNoContent() {
  return new NextResponse(null, { status: 204 });
}

export function handleApiError(error: unknown) {
  if (isApiError(error)) {
    return jsonError(error);
  }

  return jsonError(internalServerError());
}

export function badRequest(message: string, detail?: string) {
  return new ApiError('BAD_REQUEST', message, { detail });
}

export function unauthorized(message = 'Unauthorized') {
  return new ApiError('UNAUTHORIZED', message);
}

import 'server-only';

import { NextResponse } from 'next/server';

export type ApiErrorCode =
  | 'BAD_REQUEST'
  | 'UNAUTHORIZED'
  | 'FORBIDDEN'
  | 'NOT_FOUND'
  | 'CONFLICT'
  | 'VALIDATION_ERROR'
  | 'INTERNAL_SERVER_ERROR'
  | 'SERVICE_UNAVAILABLE';

export interface ApiErrorBody {
  code: ApiErrorCode;
  message: string;
  detail?: string;
  fields?: Record<string, string>;
}

export class ApiError extends Error {
  readonly code: ApiErrorCode;
  readonly status: number;
  readonly detail?: string;
  readonly fields?: Record<string, string>;

  constructor(
    code: ApiErrorCode,
    message: string,
    options: {
      status?: number;
      detail?: string;
      fields?: Record<string, string>;
      cause?: unknown;
    } = {}
  ) {
    super(message, { cause: options.cause });
    this.name = 'ApiError';
    this.code = code;
    this.status = options.status ?? statusByCode[code];
    this.detail = options.detail;
    this.fields = options.fields;
  }
}

const statusByCode: Record<ApiErrorCode, number> = {
  BAD_REQUEST: 400,
  UNAUTHORIZED: 401,
  FORBIDDEN: 403,
  NOT_FOUND: 404,
  CONFLICT: 409,
  VALIDATION_ERROR: 422,
  INTERNAL_SERVER_ERROR: 500,
  SERVICE_UNAVAILABLE: 503,
};

export function isApiError(error: unknown): error is ApiError {
  return error instanceof ApiError;
}

export function toApiErrorBody(error: ApiError): ApiErrorBody {
  return {
    code: error.code,
    message: error.message,
    ...(error.detail ? { detail: error.detail } : {}),
    ...(error.fields ? { fields: error.fields } : {}),
  };
}

export function jsonError(error: ApiError) {
  return NextResponse.json(toApiErrorBody(error), { status: error.status });
}

export function internalServerError() {
  return new ApiError('INTERNAL_SERVER_ERROR', 'Internal server error');
}

