      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function logoutBackendSession() {
  await request<null>('auth/logout', {
    method: 'POST',
  });
}

export async function deleteBackendAccount(accessToken: string) {
