type ContactFormHandler struct {
	svc service.ContactFormService
}

func NewContactFormHandler(svc service.ContactFormService) *ContactFormHandler {
	return &ContactFormHandler{svc: svc}
}

func (c *ContactFormHandler) Create(ctx context.Context,
	in *input.CreateContactFormInput,
) (*output.SuccessEmptyOutput, error) {
	info := client.GetClientInfo(ctx)

	req := &dto.CreateContactFormRequest{
		FirstName: in.Body.FirstName,
		LastName:  in.Body.LastName,
		Email:     in.Body.Email,
		Subject:   in.Body.Subject,
		Message:   in.Body.Message,
	}

	if info != nil {
		req.IPAddr = info.IP
		req.UserAgent = info.UserAgent
	}

	err := c.svc.Create(ctx, req)
	if err != nil {
		return nil, output.NewErrorOutput(err)
	}

	return output.NewSuccessEmptyOutput(), nil
}

