		Email:     req.Email.String(),
		Type:      object.NonResidentTypeIndividual,
		CountryID: req.CountryID,
	})
	if err != nil {
		if errs.IsDuplicateKeyError(err, "non_resident_waitlists_email_key") {
			return errs.NewAppError(errs.Conflict, "email already exists", 409).WithError(err)
		}

		if errs.IsForeignKeyError(err, "non_resident_waitlists_country_id_fkey") {
			return errs.NewAppError(errs.BadRequest, "invalid country ID", 400).WithError(err)
		}

		n.logger.Error("failed to create individual form", "error", err, "email", req.Email)

		return errs.NewAppError(errs.Database, "failed to create individual form", 500).WithError(err)
	}

	return nil
