package output

import (
	"errors"

	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/InfraFund-net7/backpro/pkg/pagination"
)

const (
	OKCode        = "OK"
	CreatedCode   = "CREATED"
	NoContentCode = "NO_CONTENT"
)

type SuccessOutput[T any] struct {
	Code int `header:"X-Status-Code" json:"-"`
	Body *SuccessResponse[T]
}

func NewSuccessOutput[T any](resp T) *SuccessOutput[T] {
	return &SuccessOutput[T]{
		Code: 200,
		Body: &SuccessResponse[T]{
			Code: OKCode,
			Data: resp,
		},
	}
}

type ListOutput[T any] struct {
	Code int `header:"X-Status-Code" json:"-"`
	Body *PaginatedResponse[T]
}

func NewListOutput[T any](resp []T, pagination pagination.Pagination) *ListOutput[T] {
	return &ListOutput[T]{
		Code: 200,
		Body: &PaginatedResponse[T]{
			Code:       OKCode,
			Data:       resp,
			Pagination: pagination,
		},
	}
}

func NewErrorOutput(err error) error {
	var appErr *errs.AppError
	ok := errors.As(err, &appErr)
	if !ok {
		appErr = errs.NewAppError(errs.ErrInternal.Code, err.Error(), errs.ErrInternal.StatusCode).WithError(err)
	}

	return appErr.ToHuma()
}

type SuccessEmptyOutput struct {
	Code int `header:"X-Status-Code" json:"-"`
}

func NewSuccessEmptyOutput() *SuccessEmptyOutput {
	return &SuccessEmptyOutput{
		Code: 204,
	}
}

type SuccessCreatedOutput[T any] struct {
	Code int `header:"X-Status-Code" json:"-"`
	Body *SuccessResponse[T]
}

func NewSuccessCreatedOutput[T any](resp T) *SuccessCreatedOutput[T] {
	return &SuccessCreatedOutput[T]{
		Code: 201,
		Body: &SuccessResponse[T]{
			Code: CreatedCode,
			Data: resp,
		},
	}
}

type SuccessResponse[T any] struct {
	Code string `json:"code" example:"OK" doc:"Response code indicating success"`
	Data T      `json:"data"`
}

type PaginatedResponse[T any] struct {
	Code       string                `json:"code" example:"OK"`
	Data       []T                   `json:"data"`
	Pagination pagination.Pagination `json:"pagination"`
}

import 'server-only';

import { PrismaPg } from '@prisma/adapter-pg';
import { PrismaClient } from '@prisma/client';

import { requireServerEnv } from '@/server/env';

const globalForPrisma = globalThis as unknown as {
  prisma?: PrismaClient;
};

let prisma = globalForPrisma.prisma;

function createPrismaClient() {
  const env = requireServerEnv(['database']);
  const adapter = new PrismaPg(env.database.url!);

  return new PrismaClient({
    adapter,
    log:
      process.env.NODE_ENV === 'development'
        ? ['query', 'error', 'warn']
        : ['error'],
  });
}

export function getDb() {
  prisma ??= createPrismaClient();

  if (process.env.NODE_ENV !== 'production') {
    globalForPrisma.prisma = prisma;
  }

  return prisma;
}

package middleware

import (
	"github.com/danielgtaylor/huma/v2"
	"github.com/gofiber/fiber/v2"
	"github.com/ja7ad/captcha"
)

const recaptchaHeaderKey = "X-Captcha-Token"

func Recaptcha(api huma.API, rcap captcha.Captcha) func(ctx huma.Context, next func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		if rcap == nil {
			next(ctx)

			return
		}

		challengeKey := extractChallengeKeyFromHeader(ctx)
		if challengeKey == "" {
			_ = huma.WriteErr(api, ctx, fiber.StatusBadRequest, "missing recaptcha challenge key in header")

			return
		}

		ok, err := rcap.Validate(ctx.Context(), challengeKey, ctx.RemoteAddr())
		if err != nil {
			_ = huma.WriteErr(api, ctx, fiber.StatusInternalServerError, "failed to verify captcha", err)

			return
		}

		if !ok {
			_ = huma.WriteErr(api, ctx, fiber.StatusUnauthorized, "captcha verification failed", err)

			return
		}

		next(ctx)
	}
}

func extractChallengeKeyFromHeader(ctx huma.Context) string {
	token := ctx.Header(recaptchaHeaderKey)

	return token
}

package contactform

import (
	"bytes"
	"context"
	"fmt"

	"github.com/InfraFund-net7/backpro/internal/application/contact_form/dto"
	"github.com/InfraFund-net7/backpro/internal/domain/contact_form/entity"
	"github.com/InfraFund-net7/backpro/internal/domain/contact_form/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/contact_form/service"
	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/template"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/InfraFund-net7/backpro/pkg/logger"
	"github.com/InfraFund-net7/backpro/pkg/mail"
	"github.com/InfraFund-net7/backpro/pkg/mail/smtp"
)

var _ service.ContactFormService = (*ContactForm)(nil)

type ContactForm struct {
	cfRepo   repository.ContactFormRepo
	receiver string
	smtp     mail.EmailSender
	cfg      *Config
	logger   *logger.SubLogger
}

func NewContactFormService(cfRepo repository.ContactFormRepo, cfg *Config) *ContactForm {
	cf := &ContactForm{
		cfRepo:   cfRepo,
		receiver: cfg.Receiver,
		cfg:      cfg,
		logger:   logger.NewBusinessLogger("contact_form"),
	}

	if cfg.Enabled {
		smtpClient, err := smtp.NewClient(cfg.SMTP)
		if err != nil {
			cf.logger.Fatal("failed to initialize SMTP client", "error", err)
		}

		cf.smtp = smtpClient
	}

	return cf
}

func (c *ContactForm) Create(ctx context.Context, req *dto.CreateContactFormRequest) error {
	contactForm, err := entity.NewContactForm(
		req.FirstName,
		req.LastName,
		shared.NewEmail(req.Email),
		req.Subject,
		req.Message,
		req.IPAddr,
		req.UserAgent,
	)
	if err != nil {
		return err
	}

	contactForm.Status = entity.NewStatus

	if err = c.cfRepo.Create(ctx, contactForm); err != nil {
		c.logger.Error("failed to create contact form entry", "error", err)

		return errs.NewAppError(errs.Database,
			"failed to create contact form entry", 500).WithError(err)
	}

	if c.cfg.Enabled {
		c.notifyToTeam(contactForm)
	}

	return nil
}

func (c *ContactForm) notifyToTeam(form *entity.ContactForm) {
	go func() {
		subject := "[Infrafund] New Contact Form Submission"

		var buf bytes.Buffer
		err := template.ContactFormTemplate.Execute(&buf, map[string]any{
			"Name":       fmt.Sprintf("%s %s", form.FirstName, form.LastName),
			"Email":      form.Email.String(),
			"IP":         form.IP,
			"UserAgent":  form.UserAgent,
			"Subject":    form.Subject,
			"Message":    form.Message,
			"ReceivedAt": form.CreatedAt,
		})
		if err != nil {
			c.logger.Error("failed to execute contact form email template", "error", err)

			return
		}

		param := mail.Param{
			To:          c.receiver,
			Subject:     subject,
			Body:        buf.String(),
			ContentType: "text/html; charset=\"utf-8\"",
		}

		if err = c.smtp.Send(context.Background(), param); err != nil {
			c.logger.Error("failed to send contact form notification email", "error", err)

			return
		}

		c.logger.Debug("contact form notification email sent successfully", "to", c.receiver)
	}()
}

