func validateNewUserExchange(req *dto.OpenfortExchangeReq) error {
	if req.Type == "" {
		return errs.NewAppError(errs.BadRequest, "User type is required for new users.", 400)
	}

	if req.Role == "" {
		return errs.NewAppError(errs.BadRequest, "User role is required for new users.", 400)
	}

	if req.Type == object.UserTypeOrganization && strings.TrimSpace(req.OrganizationName) == "" {
		return errs.NewAppError(errs.BadRequest, "Organization name is required.", 400)
	}

	return nil
}

func (a *AuthService) validateProvisionedUser(ctx context.Context, user *userentity.User) error {
	if user.Type == object.UserTypeOrganization && user.CompanyName == "" {
		return errs.NewAppError(errs.BadRequest, "Organization name is required.", 400)
	}

	if user.Email != "" {
		if ok, err := a.userRepo.ExistsEmail(ctx, user.Email); err != nil || ok {
			if ok {
				return errs.NewAppError(errs.Conflict, "Email already in use, please try to login.", 409)
			}
			a.logger.Error("failed to check email existence", "error", err)

			return errs.NewAppError(errs.Database, "Failed to check email existence.", 500)
		}
	}

	if user.PhoneNumber != "" {
		if ok, err := a.userRepo.ExistsPhone(ctx, user.PhoneNumber); err != nil || ok {
			if ok {
				return errs.NewAppError(errs.Conflict, "Phone number already in use, please try to login.", 409)
			}
			a.logger.Error("failed to check phone existence", "error", err)

			return errs.NewAppError(errs.Database, "Failed to check phone existence.", 500)
		}
	}

	if ok, err := a.userRepo.ExistsOpenfortUserID(ctx, user.OpenfortUserID); err != nil || ok {
		if ok {
			return errs.NewAppError(errs.Conflict, "Openfort user already exists, please try to login.", 409)
		}
		a.logger.Error("failed to check openfort user existence", "error", err)

		return errs.NewAppError(errs.Database, "Failed to check openfort user existence.", 500)
	}

	return nil
}

func (a *AuthService) validateSession(sess *entity.Session) error {
	if sess.IsRevoked() {
		return errs.NewAppError(errs.Unauthorized,
			"Your session was terminated, try to login.", 401)
	}

	if sess.IsAbsolutelyExpired() {
		daysActive := int(time.Since(sess.CreatedAt).Hours() / 24)

		return errs.NewAppError(
			errs.Unauthorized,
			fmt.Sprintf("Your session has expired after %d days of use. Please login again for security.", daysActive),
			401,
		)
	}

	if sess.IsIdleExpired() {
		inactivityMinutes := int(a.cfg.ActivityTimeoutDuration.Minutes())

		return errs.NewAppError(
			errs.Unauthorized,
			"Your session expired due to inactivity after "+strconv.Itoa(inactivityMinutes)+
				" minutes. Please login again.",
			401,
		)
	}

	return nil
}

}

func (o *Openfort) GetSession(ctx context.Context, accessToken string) (*SessionResponse, error) {
	if accessToken == "" {
		return nil, errors.New("openfort: access token is required")
	}

	requestCtx, cancel := context.WithTimeout(ctx, o.timeout)
	defer cancel()

	endpoint, err := url.Parse(o.cfg.BaseURL + "/iam/v2/auth/get-session")
	if err != nil {
		return nil, fmt.Errorf("openfort: invalid base url: %w", err)
	}

	query := endpoint.Query()
	query.Set("disableCookieCache", "true")
	endpoint.RawQuery = query.Encode()

	req, err := http.NewRequestWithContext(requestCtx, http.MethodGet, endpoint.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("openfort: request creation error: %w", err)
	}

	req.Header.Set("Authorization", "Bearer "+accessToken)
	req.Header.Set("x-project-key", o.cfg.PublishableKey)

	resp, err := o.client.Do(req)
	if err != nil {
		o.logger.Error("openfort session request failed", "error", err.Error())

		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("openfort: read error: %w", err)
	}

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		o.logger.Warn("openfort session validation failed", "status", resp.StatusCode, "body", string(body))

		return nil, fmt.Errorf("openfort: get session failed with status %d", resp.StatusCode)
	}

	var session SessionResponse
	if err := json.Unmarshal(body, &session); err != nil {
		return nil, fmt.Errorf("openfort: unmarshal error: %w", err)
	}

	if session.User.ID == "" {
		return nil, errors.New("openfort: missing user id in session response")
	}

	return &session, nil
}

