import (
	"time"

	"github.com/InfraFund-net7/backpro/internal/infrastructure/external/openfort"
	"github.com/InfraFund-net7/backpro/pkg/crypto"
)

type Config struct {
	Jwt                     *crypto.Config   `koanf:"jwt"`
	Openfort                *openfort.Config `koanf:"openfort"`
	AbsoluteExpiresDuration time.Duration    `koanf:"absolute_expires_duration"`
	ActivityTimeoutDuration time.Duration    `koanf:"activity_timeout_duration"`

	MaxFailedAttempts  int16         `koanf:"-"`
	LockoutDuration    time.Duration `koanf:"-"`
	AttemptResetWindow time.Duration `koanf:"-"`
	MinAttemptInterval time.Duration `koanf:"-"`
}

func DefaultConfig() *Config {
	return &Config{
		Jwt:                     crypto.DefaultConfig(),
		Openfort:                openfort.DefaultConfig(),
		AbsoluteExpiresDuration: 7 * 24 * time.Hour,
		ActivityTimeoutDuration: 15 * time.Minute,
		MaxFailedAttempts:       10,
		LockoutDuration:         30 * time.Minute,
		AttemptResetWindow:      24 * time.Hour,
		MinAttemptInterval:      100 * time.Millisecond,
	}
}

func (c *Config) BasicCheck() error {
	if err := c.Jwt.BasicCheck(); err != nil {
		return err
	}

	return c.Openfort.BasicCheck()
}
